try:
    import urllib.request
    r = urllib.request.urlopen("https://example.com", timeout=10)
    print("HTTP", r.status)
except BaseException as e:
    print('URLLIB caught', type(e).__name__, str(e)[:300])

try:
    from pyodide.http import pyfetch
    r = await pyfetch("https://example.com")
    print("HTTP", r.status)
except BaseException as e:
    print('PYFETCH caught', type(e).__name__, str(e)[:300])
